            background:
              'A Entidade de Turismo do Lago Bled (LBTB) gere 1,27 milhões de visitantes anuais no lago mais icónico da Eslovénia — um Geoparque Global da UNESCO. Em 2023, testes de qualidade da água revelaram um aumento de 14% nos níveis de microplásticos atribuído a fugas de combustível de lanchas a motor e tinta abrasiva de cascos de embarcações de aluguer. A Diretora de Turismo Sustentável, Dra. Ana Kovacic, enfrentava pressão da autoridade do Parque Nacional de Triglav para reduzir as embarcações motorizadas em 60% até 2026 sob risco de perder a designação da UNESCO. O perímetro de 6 km do lago e a profundidade média de 30,2 m tornavam-no ideal para desportos aquáticos não motorizados, mas os operadores de aluguer existentes tinham investido €2,3 milhões em frotas de lanchas a motor.',
