            background:
              'A Camp Keowee, um campamento residencial de verão no Lago Jocassee (3.036 hectares, 91 m de profundidade) fundado em 1937, recebe 1.200 campistas anualmente em 4 sessões de duas semanas. A Diretora de Atividades Aquáticas, Megan Whitfield, descobriu que 65% dos campistas nunca escolhiam as ofertas tradicionais existentes de canoa e caiaque do campamento (23 canoas Old Town, 18 caiaques Perception) em vez de atividades mais adrenalínicas como esqui aquático e tubbing. Whitfield, ex-instrutora da NOLS, queria introduzir o SUP como ferramenta de exploração — não apenas uma atividade de pagaia — com componentes de competências científicas e de vida selvagem que apelavam ao perfil de campista «curioso pela natureza» (dos 8 aos 15 anos).',
            goal: 'Desenvolver um programa de distintivos de Exploração SUP de 4 níveis que envolva mais de 500 campistas únicos por verão com progressão mensurável de competências e resultados de diário de natureza.',
