            goal: 'Implementar um sistema de salvamento de resposta rápida baseado em SUP alcançando mobilização em menos de 60 segundos e capacidade de primeiro contacto em todos os 11 clubes de surf da Gold Coast até ao verão australiano de 2025-26.',
