            goal: 'Estabelecer uma Unidade de Salvamento SUP de 12 pranchas capaz de intervenção de primeiro contacto na rebentação e zonas de águas rasas em menos de 90 segundos após o despacho, com equipamento de trauma e spinal integrado.',
